<span class="line"><span class="__shiki_140thh">    @</span><span class="__shiki_1itgoe">Before</span><span class="__shiki_140thh">(</span><span class="__shiki_mdbnqw">&quot;execution(* com.service.*.*(..))&quot;</span><span class="__shiki_140thh">)</span></span>
