<span class="line"><span class="__shiki_140thh">        System.out.</span><span class="__shiki_1t8gfj">println</span><span class="__shiki_140thh">(</span><span class="__shiki_mdbnqw">&quot;方法调用: &quot;</span><span class="__shiki_1itgoe"> +</span><span class="__shiki_140thh"> jp.</span><span class="__shiki_1t8gfj">getSignature</span><span class="__shiki_140thh">());</span></span>
